    // This means that the parentheses are at the beginning or end of the expression and are
    // equal to the range of the expression to be evaluated. Return 1 to avoid zero factors in
    // equation (a * b * c).
    if (left == right) {
        return 1;
    }
    int number = 0;
    for (int i = left; i < right; i++) {
